def lps(str):
    n = len(str)
    if n == 0:
        return 0
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][0] = i
    for i in range(1, n):
        dp[i][1] = i
    for i in range(1, n):
        for j in range(i):
            if str[i] == str[j]:
                dp[i][1] = max(dp[i][1], dp[j][0] + 1)
    for i in range(1, n):
        for j in range(i, n):
            if str[i] == str[j]:
                dp[i][1] = max(dp[i][1], dp[i][0] + dp[j][0])
    return max(row) for row in dp

